#include <stdlib.h>
#include <string.h>
#include <omp.h>

#define MR 6
#define NR 16
#define KC 256
#define MC 72
#define NCG 128

typedef float v8 __attribute__((vector_size(32)));

static inline v8 ldu(const float *p) { v8 v; memcpy(&v, p, sizeof(v)); return v; }
static inline void stu(float *p, v8 v) { memcpy(p, &v, sizeof(v)); }

static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict c, int ldc, int mr, int nr, int accum)
{
    v8 c00 = {0}, c01 = {0}, c10 = {0}, c11 = {0}, c20 = {0}, c21 = {0};
    v8 c30 = {0}, c31 = {0}, c40 = {0}, c41 = {0}, c50 = {0}, c51 = {0};

    for (int k = 0; k < kc; k++) {
        v8 b0 = *(const v8 *)(b + 16 * k);
        v8 b1 = *(const v8 *)(b + 16 * k + 8);
        const float *ap = a + 6 * k;
        float a0 = ap[0], a1 = ap[1], a2 = ap[2], a3 = ap[3], a4 = ap[4], a5 = ap[5];
        c00 += a0 * b0; c01 += a0 * b1;
        c10 += a1 * b0; c11 += a1 * b1;
        c20 += a2 * b0; c21 += a2 * b1;
        c30 += a3 * b0; c31 += a3 * b1;
        c40 += a4 * b0; c41 += a4 * b1;
        c50 += a5 * b0; c51 += a5 * b1;
    }

    v8 acc[6][2] = {{c00, c01}, {c10, c11}, {c20, c21},
                    {c30, c31}, {c40, c41}, {c50, c51}};

    if (nr == NR) {
        for (int i = 0; i < mr; i++) {
            float *cp = c + (size_t)i * ldc;
            if (accum) {
                stu(cp, ldu(cp) + acc[i][0]);
                stu(cp + 8, ldu(cp + 8) + acc[i][1]);
            } else {
                stu(cp, acc[i][0]);
                stu(cp + 8, acc[i][1]);
            }
        }
    } else {
        float tmp[MR][NR] __attribute__((aligned(64)));
        for (int i = 0; i < MR; i++) {
            stu(&tmp[i][0], acc[i][0]);
            stu(&tmp[i][8], acc[i][1]);
        }
        for (int i = 0; i < mr; i++) {
            float *cp = c + (size_t)i * ldc;
            int j = 0;
            if (nr >= 8) {
                if (accum) stu(cp, ldu(cp) + acc[i][0]);
                else stu(cp, acc[i][0]);
                j = 8;
            }
            if (accum)
                for (; j < nr; j++) cp[j] += tmp[i][j];
            else
                for (; j < nr; j++) cp[j] = tmp[i][j];
        }
    }
}

static float *g_Abuf, *g_Bbuf;
static size_t g_capA, g_capB;

static float *grow(float *p, size_t *cap, size_t need)
{
    if (need <= *cap && p) return p;
    free(p);
    size_t bytes = (need * sizeof(float) + 63) & ~(size_t)63;
    if (bytes == 0) bytes = 64;
    p = (float *)aligned_alloc(64, bytes);
    *cap = need;
    return p;
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;

    int rp = (n + MR - 1) / MR;
    int cpn = (n + NR - 1) / NR;
    size_t szA = (size_t)rp * MR * KC;
    size_t szB = (size_t)cpn * NR * KC;
    g_Abuf = grow(g_Abuf, &g_capA, 2 * szA);
    g_Bbuf = grow(g_Bbuf, &g_capB, 2 * szB);
    float *Abuf = g_Abuf, *Bbuf = g_Bbuf;

    int nib = (n + MC - 1) / MC;
    int njb = (n + NCG - 1) / NCG;
    int nitems = nib * njb;

    #pragma omp parallel
    {
        int parity = 0;
        for (int pc = 0; pc < n; pc += KC, parity ^= 1) {
            int kc = n - pc < KC ? n - pc : KC;
            int accum = pc > 0;
            float *Ap = Abuf + parity * szA;
            float *Bp = Bbuf + parity * szB;

            /* pack A[:, pc:pc+kc] into MR-row panels */
            #pragma omp for schedule(static) nowait
            for (int ip = 0; ip < rp; ip++) {
                float *dst = Ap + (size_t)ip * kc * MR;
                int i0 = ip * MR;
                int mr = n - i0 < MR ? n - i0 : MR;
                if (mr == MR) {
                    const float *s0 = A + (size_t)(i0 + 0) * n + pc;
                    const float *s1 = A + (size_t)(i0 + 1) * n + pc;
                    const float *s2 = A + (size_t)(i0 + 2) * n + pc;
                    const float *s3 = A + (size_t)(i0 + 3) * n + pc;
                    const float *s4 = A + (size_t)(i0 + 4) * n + pc;
                    const float *s5 = A + (size_t)(i0 + 5) * n + pc;
                    for (int k = 0; k < kc; k++) {
                        float *d = dst + k * MR;
                        d[0] = s0[k]; d[1] = s1[k]; d[2] = s2[k];
                        d[3] = s3[k]; d[4] = s4[k]; d[5] = s5[k];
                    }
                } else {
                    for (int k = 0; k < kc; k++) {
                        float *d = dst + k * MR;
                        int ii = 0;
                        for (; ii < mr; ii++) d[ii] = A[(size_t)(i0 + ii) * n + pc + k];
                        for (; ii < MR; ii++) d[ii] = 0.0f;
                    }
                }
            }

            /* pack B[pc:pc+kc, :] into NR-wide panels; the barrier at the end
               also covers the A pack */
            #pragma omp for schedule(static)
            for (int jp = 0; jp < cpn; jp++) {
                float *dst = Bp + (size_t)jp * kc * NR;
                int j0 = jp * NR;
                int nr = n - j0 < NR ? n - j0 : NR;
                if (nr == NR) {
                    for (int k = 0; k < kc; k++)
                        memcpy(dst + k * NR, B + (size_t)(pc + k) * n + j0, NR * sizeof(float));
                } else {
                    for (int k = 0; k < kc; k++) {
                        const float *src = B + (size_t)(pc + k) * n + j0;
                        float *d = dst + k * NR;
                        int j = 0;
                        for (; j < nr; j++) d[j] = src[j];
                        for (; j < NR; j++) d[j] = 0.0f;
                    }
                }
            }

            /* compute; double buffering plus the next B-pack barrier make a
               trailing barrier unnecessary */
            #pragma omp for schedule(dynamic, 1) nowait
            for (int it = 0; it < nitems; it++) {
                int ib = it / njb, jb = it % njb;
                int ic = ib * MC;
                int mc = n - ic < MC ? n - ic : MC;
                int jc = jb * NCG;
                int nc = n - jc < NCG ? n - jc : NCG;

                for (int jr = 0; jr < nc; jr += NR) {
                    int j = jc + jr;
                    int nr = n - j < NR ? n - j : NR;
                    const float *bp = Bp + (size_t)(j / NR) * kc * NR;
                    for (int ir = 0; ir < mc; ir += MR) {
                        int i = ic + ir;
                        int mr = n - i < MR ? n - i : MR;
                        kernel(kc, Ap + (size_t)(i / MR) * kc * MR, bp,
                               C + (size_t)i * n + j, n, mr, nr, accum);
                    }
                }
            }
        }
    }
}
